import{H as l,_ as h}from"./page-accent-C87MlHoR.js";import{A as u,_ as o}from"./landmark-down-MR1kzCsi.js";import{d,_ as m,c,a,b as t,r as n,f as s,F as f,o as g}from"./index-VGGXj3wy.js";import{_ as i}from"./cross-roads-spacer-CfnfYCMt.js";const y=d({components:{Header:l,AudioPlayer:u}}),w={class:"project-section",id:"overview"};function b(v,e,I,k,T,x){const r=n("Header"),p=n("AudioPlayer");return g(),c(f,null,[a(r),e[9]||(e[9]=t("img",{src:h,alt:"",class:"page-decoration"},null,-1)),t("main",null,[e[4]||(e[4]=t("h1",null,"The Group Improvisation",-1)),e[5]||(e[5]=t("h2",null,"Page Contents",-1)),e[6]||(e[6]=t("nav",{class:"page-nav"},[t("a",{href:"#overview"},"Overview"),t("a",{href:"#performance"},"Performance"),t("a",{href:"#reflections"},"Reflections")],-1)),t("div",w,[e[0]||(e[0]=t("h2",null,"Overview",-1)),e[1]||(e[1]=t("p",{class:"subheading"},"Listen to text",-1)),e[2]||(e[2]=t("img",{src:o,alt:"",class:"landmark"},null,-1)),a(p,{src:"text-audio/improvisation-overview.mp3"}),e[3]||(e[3]=s('<p class="subheading">Or read (1 minute)</p><img src="'+o+'" alt="" class="landmark"><p> Jean-Luc Guionnet and Seijiro Murayama came to the University of Huddersfield to lead an improvisation workshop. The workshop allowed us to explore new methods of sound-making, and taught us about sharing space with different performers. From this, we took part in a group performance at the CeReNeM Journal Showcase. </p><div class="spacer"><a href="#">Back to contents</a><img style="padding-left:30px;" src="'+i+'" alt=""></div>',4))]),e[7]||(e[7]=t("div",{class:"project-section",id:"performance"},[t("h2",null,"Performance"),t("iframe",{src:"https://www.youtube.com/embed/8QivTe--WD4?si=zJ9I8bsSJ9Jo80T2",title:"YouTube video player",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:""}),t("div",{class:"spacer"},[t("a",{href:"#"},"Back to contents"),t("img",{style:{"padding-left":"30px"},src:i,alt:""})])],-1)),e[8]||(e[8]=s('<div class="project-section" id="reflections"><h2>Reflections</h2><h3>Freya</h3><p class="subheading">Read (1 minute)</p><img src="'+o+'" alt="" class="landmark"><p> I played a flamenco guitar for my solo improvisation [...] for the most part, I avoided traditional flamenco techniques, instead using a cello bow for scraping and creaking sounds </p><p> [My] approach was inspired by the workshop by Jean-Luc Guionnet and Seijiro Murayama, who discussed techniques for detaching from an instrument’s conventional idioms and breaking free from traditional constraints. This does not preclude common idioms but encourages reconceptualisation of how an instrument is approached. </p><p> Despite my inexperience with contemporary on-stage improvisation compared to my peers, I was pleased with the performance’s haunting soundscape. </p><h3>Jo</h3><p class="subheading">Read (1 minute)</p><img src="'+o+'" alt="" class="landmark"><p>Start with white and add colour</p><p>The space makes the sound</p><br><p>The solo is always playing inside you</p><br><p>Listen to other people.</p><br><p>Coming into silence is very imposing</p><br><p> Improvising for me has been about creating a dense atmosphere, the specifics of the sound aren&#39;t always the most important element… </p><h3>Sophie</h3><p class="subheading">Read (1 minute)</p><img src="'+o+'" alt="" class="landmark"><p>An interesting experience!</p><p> Seijiro Murayama had us taking part in movement exercises that I personally found a bit cringe worthy and something I would normally run miles away from taking part in due to deep rooted, long term embarrassment associated with the body and early childhood experiences. Not for me, basically! Physically navigating around the other people in the group and the room itself can be seen as similar to how sound and music moves around an auditory space during an improvisation. You’ve got to be careful not to trip someone else up. </p><p> Personally, the most useful feedback I received from Jean-Luc was a comment about how I tend to create a groove / loop when improvising on the trombone which becomes a sort of sonic-trap that is hard to escape from, and I agree with this. </p><p> I suppose the answer is, knowing that I have this tendency, to practice improvisation tricks a bit more and either look for obvious exit signs or just go wild and smash through the walls </p><h3>Tom</h3><div id="tom-writing"><p> One of the biggest challenges I face as an improviser and composer is working out what my music is. </p><p> Prior to the workshop with Seijiro and Jean-Luc, I would have described improvising as a difficult balance between making my music and allowing everyone else’s music space to breathe. </p><p> The main thing I learnt from this experience was that I can make my own music and at the same time provide space for others to make their music. </p><p> My music or ‘necessity’ as Seijro put it feels somewhat irrelevant and what now feels significant is when my music occurs </p><p> I am still full of questions, but these are focused around a positive angle: what can my music become with the company of others? This is something which fills me with optimism about the future of my music. </p><p> There is no doubt that a synthesiser can make a louder sound than an acoustic cello, but if the aim of the improvisation is not a rise to a climax, then the volume levels of these instruments may not be an issue. Working together can unlock a new music which doesn’t compromise the musical necessity of either instrument. </p></div><h3>Anthony</h3><p class="subheading">Read (1 minute)</p><img src="'+o+'" alt="" class="landmark"><p>Improvisation</p><br><p>[My Necessity]</p><p>“Of course I have this background, but how to share?”</p><p>**Preparation, Desperation, Burden**</p><br><p>[Inside // Outside]</p><p>“Come from somewhere…not here…change the space”</p><p>**Interjection**</p><ul><li>Assasin</li><li>Digging</li><li>Event</li></ul><p>**Hiding**</p><ul><li>Pulse</li><li>Imagination</li></ul><br><p>[Discontinuity // Continuity]</p><p>“Go your own way…connect when possible.&quot;</p><p>“Cutting…it gives a new vision.”</p><p>“And once again, start.”</p><br><p>[...]</p><br><p>“Music happens sometimes…”</p><h3>Charlotte</h3><p class="subheading">Read (2 minutes)</p><img src="'+o+'" alt="" class="landmark"><p>PART 1: Not a musician</p><p> It&#39;s strange to write about this now, because it&#39;s a sentiment I&#39;ve left behind, and was probably on the cusp of leaving behind at the time of starting the improv workshop, but funnily enough I did begin my MA in Music thinking of myself as &#39;not a musician&#39;. </p><p>Reasons for this classification:</p><ul><li>I dropped Music in Year 9</li><li>I&#39;ve never had instrument lessons of any sort</li><li>I can&#39;t read or write traditional notation</li><li>I can&#39;t identify by ear: notes, chords, keys, time signatures</li></ul><p> I think my path has actually been a relatively common one. I came from visual art, into &#39;sound art&#39;, into noise-based music, and now that&#39;s where my practice sits: noise, computer music, electronics, glitch etc. </p><p> By this time I had started performing some of my &#39;sound art&#39;, and was coming round to the idea that I might be a musician, but definitely not an improviser. All my performances were pre-planned and rehearsed. </p><p> The reason I mention this is I had gone into the workshop thinking, at least for the first day, I would just listen and not take part. I wasn&#39;t an improviser, so who knows what would be expected of me? </p><p>That I take part, for one.</p><p>PART 2: A series of ERRORS</p><p> So I took out my beloved decrepit old laptop, running a fresh install of Ubuntu that I had yet to re-setup with SuperCollider &amp; TidalCycles, and tried to find something I could play. </p><p> I had a little digital instrument / browser tool / performance UI (I&#39;m still not sure what I call them) that I had recently built to perform with called &#39;Clock&#39;. </p><p> It&#39;s a grid of 365 buttons. A number which is related to the ✨ concept ✨ of the piece for which it was built, but arbitrary for this new purpose. Each button can be switched on to output white noise through a band pass filter tuned to a frequency taken from a dataset containing some numbers also only 🌼 meaningful 🌼 in another context. </p><p> There&#39;s some automation on the original version of Clock, blocks of buttons are briefly switched on at set intervals throughout the performance. </p><p> There are keyboard shortcuts to play: all the low, medium, or high frequencies, a random frequency, a reverse of the currently selected buttons, all the buttons, and to switch off all the currently playing buttons. </p><p>I decided I could use this as long as I removed the automation.</p><p> The first improv began, everyone in a big circle doing solo-duo, I took a spot in the circle where I could plug in my laptop and started to edit the code. I think the first time I was meant to play I said I wasn&#39;t ready, but the second I produced a very quiet little bunch of sounds directly out of my laptop speakers. </p><p>Woah - improvisation!</p><p> I found time to improve my instrument&#39;s suitability for improv throughout the day: standardising the frequency range to evenly spaced values, and upping the max gain to I could get more volume out of my laptop speakers. </p><p>I think the latter is what broke the speaker.</p><p> Half way through an exercise it started doing this, and honestly it was super fun, I couldn&#39;t modulate the sound via Clock anymore so I just had to physically move the computer around to have the sound bounce and resonate in different ways. </p><p>Improvisation 😎</p><p> All good I thought, I have a shiny new MacBook and nice monitor at home, I can bring this tomorrow, it will be my rig. I&#39;ll buy one of those hard shell suitcases to transport it. </p><p> I locked my new suitcase with a code - and must have set it up wrong, because I couldn&#39;t get back in. Luckily, Jo Christman always carries a screwdriver, but I had to wait until lunch to break in and free my tech. </p><p>PART 3: Metronome+</p><p> Seijiro told me his favourite instrument to improvise with is a metronome. I have a metronome app on my phone. </p><p>Improvisation 💃</p><p> What&#39;s great about using the metronome is you get to practice constraint. I begin by thinking &#39;ok I can modulate the bpm and the &#39;voice&#39;, that&#39;s probably enough&#39;, but Seijiro encouraged me to stick with one voice, and one (fairly slow) BPM. </p><p> I remember one solitary &#39;click&#39; in the middle of some silence being one of my favourite gestures I made during the workshop. </p><p> Structuring this writing how I have isn&#39;t to imply that I undertook some kind of linear hero&#39;s journey from non-improviser to improviser over the course of three days. I actually found the workshop immediately engaging, accessible, and understandable. </p><p> I wonder if my lack of musician-y background helped me get into the idea of non-idiomatic improv easier? I wonder if playing electronics over a traditional instrument did? </p><p> There are a number of techniques and ideas I took away, and still think about when improvising now. </p><ul><li> Having a constant internal &#39;tiktikitikitik&#39; that you start/stop, surface/bury. </li><li> Considering the end of a sound just as much of an event as the start of one. </li><li> The idea of &#39;soupiness&#39;, the instinct to politely make space for every other sound in the room, waiting your turn to duck in and out. This is one approach, it isn&#39;t bad, but how do you prevent it from being the default? </li></ul><p></p><div class="spacer"><a href="#">Back to contents</a><img style="padding-left:30px;" src="'+i+'" alt=""></div></div>',1))])],64)}const P=m(y,[["render",b]]);export{P as default};
